		[TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		public void SoapWithAttachments_MimeContent_DeserializeMimeContent_EmptyAttachmentShouldProcess()
		{
			var logMock = new Mock<ILog>();
			var mimeParser = new MimeParser();
			var swaEncoderTestMock = new Mock<SwaEncoderTest>(null) { CallBase = true };

			mimeParser.logger = logMock.Object;
			swaEncoderTestMock.SetupGet(x => x.MimeParser).Returns(mimeParser);

			using (var contentStream = TestHelper.GetEmbeddedResource("TestFiles.Pull.Reply.PullReplyMultiPart_EmptyAttachment.txt"))
			{

				var message = swaEncoderTestMock.Object.ReadMessage(contentStream, int.MaxValue, @"multipart/related; boundary=""uuid:32f4d1e0-7744-4b0a-ba59-c05a08feea89""; type=""text/xml""; start=<root.message@cxf.apache.org>; charset=UTF-8");

				Assert.AreEqual(10, message.Properties.Count);
				Assert.AreEqual(4, message.Properties["swa_encoder_soap_attachment_count"]);
				Assert.IsInstanceOfType(message.Properties["swa_encoder_soap_attachment_2"], typeof(byte[]));
				Assert.AreEqual(0, ((byte[])message.Properties["swa_encoder_soap_attachment_2"]).Length);

				contentStream.Position = 0;
				var content = new StreamReader(contentStream).ReadToEnd();
				logMock.Verify(x => x.ErrorFormat(
					"Empty MimePart found, contentId: {0}, contentType: {1}, raw message: {2}",
					"<BACC_B2023_411512.pdf>",
					"application/pdf",
					content), Times.Once);
			}
		}

