		{
			var bindingElement = new TextMessageEncodingBindingElement();
			bindingElement.MessageVersion = MessageVersion.Soap11;
			var baseEncoder = bindingElement.CreateMessageEncoderFactory().Encoder;

			using (var envelopStream = TestHelper.GetEmbeddedResource("TestFiles.Lodgement.Submit.LegacyEnvelop.txt"))
			{
				var reader = XmlReader.Create(envelopStream);
				var message = Message.CreateMessage(reader, int.MaxValue, MessageVersion.Soap11);
				var encoder = new SwaEncoderTest(baseEncoder);
				encoder.Attachment = Encoding.UTF8.GetBytes("UNA:+.? 'UNB+UNOA:2+00009908C:ZZZ+CUSSWT:ZZZ+130730:1341+168'UNH+178+CUSCAR:D:98A:UN'BGM+785+B00001232+9'NAD+CA++QANTAS AIRWAYS LIMITED'TDT+20++4+++++:::QF108'LOC+22+NZAKL'DTM+132:20130730:102'GIS+10:105:143'GIS+N:109:143'CNT+10:1'CNI+1'RFF+HWB:J45829'LOC+9+AUSYD'LOC+11+NZAKL'LOC+27+AU'NAD+CN++ADULATION BOOKS LTD (NZ CUSTOMS):1 MAIN STREET:AUCKLAND AUK 2000'NAD+CZ++SUNTEC INDUSTRIAL CORP PTY LTD:33 TALLWOOD AVE:EASTWOOD NSW'GID+1+5:CT'FTX+AAA+++GOODS'MEA+WT+AAG+KGM:20.000'MOA+14:370.00:NZD'LOC+4+AUSYD'UNT+22+178'UNZ+1+168'");

