		[TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		public void SoapWithAttachments_WriteMessage_MultipleAttachments()
		{
			var bindingElement = new TextMessageEncodingBindingElement();
			bindingElement.MessageVersion = MessageVersion.Soap11;
			var baseEncoder = bindingElement.CreateMessageEncoderFactory().Encoder;

			using (var envelopStream = TestHelper.GetEmbeddedResource("TestFiles.Lodgement.Submit.WCOEnvelop.txt"))
			{
				var reader = XmlReader.Create(envelopStream);
				var message = Message.CreateMessage(reader, int.MaxValue, MessageVersion.Soap11);
				var encoder = new SwaEncoderTest(baseEncoder);

				encoder.Attachment = Convert.FromBase64String(@"");

				var bufferManager = BufferManager.CreateBufferManager(1048576, 1048576000);
				var arraySegments = encoder.WriteMessage(message, int.MaxValue, bufferManager, 0);

				using (var actualStream = new MemoryStream(arraySegments.Array.Skip(arraySegments.Offset).Take(arraySegments.Count).ToArray()))
				{
					using (var expectedStream = TestHelper.GetEmbeddedResource("TestFiles.Lodgement.Submit.MultipleAttachmentsSWA.txt"))
					{
						Assert.IsTrue(TestHelper.CompareStreams(expectedStream, actualStream), "Expected and Output streams are different");

						//using (var output = new FileStream(@"C:\eServices\eHub\Products\NZCustoms\Tests\TestFiles\Lodgement\Submit\MultipleAttachmentsSWA.txt", FileMode.Create))
						//{
						//    actualStream.CopyTo(output);
						//}
					}
				}
			}
		}

		#region Implementation

		public class SwaEncoderTest : SwaEncoder
		{
			public byte[] Attachment { get; set; }

			public SwaEncoderTest(MessageEncoder baseEncoder)
				: base(baseEncoder)
			{
			}

			protected override void VerifyOperationContext()
			{
			}

			protected override byte[] GetAttachment()
			{
				return Attachment;
			}

			protected override MimeContent CreateMimeContentWithSOAPPart()
			{
				var soapMimeContent = new MimePart("text/xml", "binary", "SOAPPartContentId", "UTF-8");
				var myContent = new MimeContent("BOUNDARYSEPARATOR");
				myContent.AddPart(soapMimeContent);
				return myContent;
			}

			protected override MimePart CreateAttacmentMimePart(LodgementDocument attachment)
			{
				return new MimePart(attachment.DocumentMediaType, "binary", attachment.FileName);
			}
		}

		#endregion
	}
